111	function getBoundingDiff(points1: ArrayLike<number>, points2: ArrayLike<number>): number {
112	
113	    const [min1, max1] = bboxFromPoints(points1);
114	    const [min2, max2] = bboxFromPoints(points2);
115	
116	    // Get a max value from each corner of two boundings.
