40	export function prepareDataCoordInfo(
41	    coordSys: Cartesian2D | Polar,
42	    data: SeriesData,
43	    valueOrigin?: LineSeriesOption['areaStyle']['origin']
44	): CoordInfo {
45	    const baseAxis = coordSys.getBaseAxis();
46	    const valueAxis = coordSys.getOtherAxis(baseAxis as any);
47	    const valueStart = getValueStart(valueAxis, valueOrigin);
48	
49	    const baseAxisDim = baseAxis.dim;
50	    const valueAxisDim = valueAxis.dim;
51	    const valueDim = data.mapDimension(valueAxisDim);
52	    const baseDim = data.mapDimension(baseAxisDim);
53	    const baseDataOffset = valueAxisDim === 'x' || valueAxisDim === 'radius' ? 1 : 0;
54	
55	    const dims = map(coordSys.dimensions, function (coordDim) {
56	        return data.mapDimension(coordDim);
57	    });
58	
59	    let stacked = false;
60	    const stackResultDim = data.getCalculationInfo('stackResultDimension');
61	    if (isDimensionStacked(data, dims[0] /* , dims[1] */)) { // jshint ignore:line
62	        stacked = true;
63	        dims[0] = stackResultDim;
64	    }
65	    if (isDimensionStacked(data, dims[1] /* , dims[0] */)) { // jshint ignore:line
66	        stacked = true;
67	        dims[1] = stackResultDim;
68	    }
69	
70	    return {
71	        dataDimsForPoint: dims,
72	        valueStart: valueStart,
73	        valueAxisDim: valueAxisDim,
74	        baseAxisDim: baseAxisDim,
75	        stacked: !!stacked,
76	        valueDim: valueDim,
77	        baseDim: baseDim,
78	        baseDataOffset: baseDataOffset,
79	        stackedOverDimension: data.getCalculationInfo('stackedOverDimension')
80	    };
81	}
82	
83	function getValueStart(valueAxis: Axis, valueOrigin: LineSeriesOption['areaStyle']['origin']) {
84	    let valueStart = 0;
85	    const extent = valueAxis.scale.getExtent();
86	
87	    if (valueOrigin === 'start') {
88	        valueStart = extent[0];
89	    }
90	    else if (valueOrigin === 'end') {
91	        valueStart = extent[1];
92	    }
93	    // If origin is specified as a number, use it as
94	    // valueStart directly
95	    else if (isNumber(valueOrigin) && !isNaN(valueOrigin)) {
96	        valueStart = valueOrigin;
97	    }
98	    // auto
99	    else {
100	        // Both positive
101	        if (extent[0] > 0) {
102	            valueStart = extent[0];
103	        }
104	        // Both negative
105	        else if (extent[1] < 0) {
106	            valueStart = extent[1];
107	        }
108	        // If is one positive, and one negative, onZero shall be true
109	    }
110	
111	    return valueStart;
112	}
113	
114	export function getStackedOnPoint(
115	    dataCoordInfo: CoordInfo,
116	    coordSys: Cartesian2D | Polar,
117	    data: SeriesData,
118	    idx: number
119	) {
120	    let value = NaN;
121	    if (dataCoordInfo.stacked) {
122	        value = data.get(data.getCalculationInfo('stackedOverDimension'), idx) as number;
123	    }
124	    if (isNaN(value)) {
125	        value = dataCoordInfo.valueStart;
126	    }
127	
128	    const baseDataOffset = dataCoordInfo.baseDataOffset;
129	    const stackedData = [];
130	    stackedData[baseDataOffset] = data.get(dataCoordInfo.baseDim, idx);
131	    stackedData[1 - baseDataOffset] = value;
132	
133	    return coordSys.dataToPoint(stackedData);
134	}
