34	/**
35	 * Draw smoothed line in non-monotone, in may cause undesired curve in extreme
36	 * situations. This should be used when points are non-monotone neither in x or
37	 * y dimension.
38	 */
39	function drawSegment(
40	    ctx: PathProxy,
41	    points: ArrayLike<number>,
42	    start: number,
43	    segLen: number,
44	    allLen: number,
45	    dir: number,
46	    smooth: number,
47	    smoothMonotone: 'x' | 'y' | 'none',
48	    connectNulls: boolean
49	) {
50	    let prevX: number;
51	    let prevY: number;
52	    let cpx0: number;
53	    let cpy0: number;
54	    let cpx1: number;
55	    let cpy1: number;
56	    let idx = start;
57	    let k = 0;
58	    for (; k < segLen; k++) {
59	
60	        let x = points[idx * 2];
61	        let y = points[idx * 2 + 1];
62	
63	        if (idx >= allLen || idx < 0) {
64	            break;
65	        }
66	        if (isPointNull(x, y)) {
67	            if (connectNulls) {
68	                idx += dir;
69	                continue;
70	            }
71	            break;
72	        }
73	
74	        if (idx === start) {
75	            ctx[dir > 0 ? 'moveTo' : 'lineTo'](x, y);
76	            cpx0 = x;
77	            cpy0 = y;
78	        }
79	        else {
80	            let dx = x - prevX;
81	            let dy = y - prevY;
82	
83	            // Ignore tiny segment.
84	            if ((dx * dx + dy * dy) < 0.5) {
85	                idx += dir;
86	                continue;
87	            }
88	
89	            if (smooth > 0) {
90	                let nextIdx = idx + dir;
91	                let nextX = points[nextIdx * 2];
92	                let nextY = points[nextIdx * 2 + 1];
93	                // Ignore duplicate point
94	                while (nextX === x && nextY === y && k < segLen) {
95	                    k++;
96	                    nextIdx += dir;
97	                    idx += dir;
98	                    nextX = points[nextIdx * 2];
99	                    nextY = points[nextIdx * 2 + 1];
100	                    x = points[idx * 2];
101	                    y = points[idx * 2 + 1];
102	                    dx = x - prevX;
103	                    dy = y - prevY;
104	                }
105	
106	                let tmpK = k + 1;
107	                if (connectNulls) {
108	                    // Find next point not null
109	                    while (isPointNull(nextX, nextY) && tmpK < segLen) {
110	                        tmpK++;
111	                        nextIdx += dir;
112	                        nextX = points[nextIdx * 2];
113	                        nextY = points[nextIdx * 2 + 1];
114	                    }
115	                }
116	
117	                let ratioNextSeg = 0.5;
118	                let vx: number = 0;
119	                let vy: number = 0;
120	                let nextCpx0;
121	                let nextCpy0;
122	                // Is last point
123	                if (tmpK >= segLen || isPointNull(nextX, nextY)) {
124	                    cpx1 = x;
125	                    cpy1 = y;
126	                }
127	                else {
128	                    vx = nextX - prevX;
129	                    vy = nextY - prevY;
130	
131	                    const dx0 = x - prevX;
132	                    const dx1 = nextX - x;
133	                    const dy0 = y - prevY;
134	                    const dy1 = nextY - y;
135	                    let lenPrevSeg;
136	                    let lenNextSeg;
137	                    if (smoothMonotone === 'x') {
138	                        lenPrevSeg = Math.abs(dx0);
139	                        lenNextSeg = Math.abs(dx1);
140	                        const dir = vx > 0 ? 1 : -1;
141	                        cpx1 = x - dir * lenPrevSeg * smooth;
142	                        cpy1 = y;
143	                        nextCpx0 = x + dir * lenNextSeg * smooth;
144	                        nextCpy0 = y;
145	                    }
146	                    else if (smoothMonotone === 'y') {
147	                        lenPrevSeg = Math.abs(dy0);
148	                        lenNextSeg = Math.abs(dy1);
149	                        const dir = vy > 0 ? 1 : -1;
150	                        cpx1 = x;
151	                        cpy1 = y - dir * lenPrevSeg * smooth;
152	                        nextCpx0 = x;
153	                        nextCpy0 = y + dir * lenNextSeg * smooth;
154	                    }
155	                    else {
156	                        lenPrevSeg = Math.sqrt(dx0 * dx0 + dy0 * dy0);
157	                        lenNextSeg = Math.sqrt(dx1 * dx1 + dy1 * dy1);
158	
159	                        // Use ratio of seg length
160	                        ratioNextSeg = lenNextSeg / (lenNextSeg + lenPrevSeg);
161	
162	                        cpx1 = x - vx * smooth * (1 - ratioNextSeg);
163	                        cpy1 = y - vy * smooth * (1 - ratioNextSeg);
164	
165	                        // cp0 of next segment
166	                        nextCpx0 = x + vx * smooth * ratioNextSeg;
167	                        nextCpy0 = y + vy * smooth * ratioNextSeg;
168	
169	                        // Smooth constraint between point and next point.
170	                        // Avoid exceeding extreme after smoothing.
171	                        nextCpx0 = mathMin(nextCpx0, mathMax(nextX, x));
172	                        nextCpy0 = mathMin(nextCpy0, mathMax(nextY, y));
173	                        nextCpx0 = mathMax(nextCpx0, mathMin(nextX, x));
174	                        nextCpy0 = mathMax(nextCpy0, mathMin(nextY, y));
175	                        // Reclaculate cp1 based on the adjusted cp0 of next seg.
176	                        vx = nextCpx0 - x;
177	                        vy = nextCpy0 - y;
178	
179	                        cpx1 = x - vx * lenPrevSeg / lenNextSeg;
180	                        cpy1 = y - vy * lenPrevSeg / lenNextSeg;
181	
182	                        // Smooth constraint between point and prev point.
183	                        // Avoid exceeding extreme after smoothing.
184	                        cpx1 = mathMin(cpx1, mathMax(prevX, x));
185	                        cpy1 = mathMin(cpy1, mathMax(prevY, y));
186	                        cpx1 = mathMax(cpx1, mathMin(prevX, x));
187	                        cpy1 = mathMax(cpy1, mathMin(prevY, y));
188	
189	                        // Adjust next cp0 again.
190	                        vx = x - cpx1;
191	                        vy = y - cpy1;
192	                        nextCpx0 = x + vx * lenNextSeg / lenPrevSeg;
193	                        nextCpy0 = y + vy * lenNextSeg / lenPrevSeg;
194	                    }
195	                }
196	
197	                ctx.bezierCurveTo(cpx0, cpy0, cpx1, cpy1, x, y);
198	
199	                cpx0 = nextCpx0;
200	                cpy0 = nextCpy0;
201	            }
202	            else {
203	                ctx.lineTo(x, y);
204	            }
205	        }
206	
207	        prevX = x;
208	        prevY = y;
209	        idx += dir;
210	    }
211	
212	    return k;
213	}
