227	export class ECPolyline extends Path<ECPolylineProps> {
228	
229	    readonly type = 'ec-polyline';
230	
231	    shape: ECPolylineShape;
232	
233	    constructor(opts?: ECPolylineProps) {
234	        super(opts);
235	    }
236	
237	    getDefaultStyle() {
238	        return {
239	            stroke: tokens.color.neutral99,
240	            fill: null as string
241	        };
242	    }
243	
244	    getDefaultShape() {
245	        return new ECPolylineShape();
246	    }
247	
248	    buildPath(ctx: PathProxy, shape: ECPolylineShape) {
249	        const points = shape.points;
250	
251	        let i = 0;
252	        let len = points.length / 2;
253	
254	        // const result = getBoundingBox(points, shape.smoothConstraint);
255	
256	        if (shape.connectNulls) {
257	            // Must remove first and last null values avoid draw error in polygon
258	            for (; len > 0; len--) {
259	                if (!isPointNull(points[len * 2 - 2], points[len * 2 - 1])) {
260	                    break;
261	                }
262	            }
263	            for (; i < len; i++) {
264	                if (!isPointNull(points[i * 2], points[i * 2 + 1])) {
265	                    break;
266	                }
267	            }
268	        }
269	        while (i < len) {
270	            i += drawSegment(
271	                ctx, points, i, len, len,
272	                1,
273	                shape.smooth,
274	                shape.smoothMonotone, shape.connectNulls
275	            ) + 1;
276	        }
277	    }
278	
279	    getPointOn(xOrY: number, dim: 'x' | 'y'): number[] {
280	        if (!this.path) {
281	            this.createPathProxy();
282	            this.buildPath(this.path, this.shape);
283	        }
284	        const path = this.path;
285	        const data = path.data;
286	        const CMD = PathProxy.CMD;
287	
288	        let x0;
289	        let y0;
290	
291	        const isDimX = dim === 'x';
292	        const roots: number[] = [];
293	
294	        for (let i = 0; i < data.length;) {
295	            const cmd = data[i++];
296	            let x;
297	            let y;
298	            let x2;
299	            let y2;
300	            let x3;
301	            let y3;
302	            let t;
303	            switch (cmd) {
304	                case CMD.M:
305	                    x0 = data[i++];
306	                    y0 = data[i++];
307	                    break;
308	                case CMD.L:
309	                    x = data[i++];
310	                    y = data[i++];
311	                    t = isDimX ? (xOrY - x0) / (x - x0)
312	                        : (xOrY - y0) / (y - y0);
313	                    if (t <= 1 && t >= 0) {
314	                        const val = isDimX ? (y - y0) * t + y0
315	                            : (x - x0) * t + x0;
316	                        return isDimX ? [xOrY, val] : [val, xOrY];
317	                    }
318	                    x0 = x;
319	                    y0 = y;
320	                    break;
321	                case CMD.C:
322	                    x = data[i++];
323	                    y = data[i++];
324	                    x2 = data[i++];
325	                    y2 = data[i++];
326	                    x3 = data[i++];
327	                    y3 = data[i++];
328	
329	                    const nRoot = isDimX ? cubicRootAt(x0, x, x2, x3, xOrY, roots)
330	                        : cubicRootAt(y0, y, y2, y3, xOrY, roots);
331	                    if (nRoot > 0) {
332	                        for (let i = 0; i < nRoot; i++) {
333	                            const t = roots[i];
334	                            if (t <= 1 && t >= 0) {
335	                                const val = isDimX ? cubicAt(y0, y, y2, y3, t)
336	                                    : cubicAt(x0, x, x2, x3, t);
337	                                return isDimX ? [xOrY, val] : [val, xOrY];
338	                            }
339	                        }
340	                    }
341	
342	                    x0 = x3;
343	                    y0 = y3;
344	                    break;
345	            }
346	        }
347	    }
348	}
