364	    constructor(opts?: ECPolygonProps) {
365	        super(opts);
366	    }
367	
368	    getDefaultShape() {
369	        return new ECPolygonShape();
370	    }
371	
372	    buildPath(ctx: PathProxy, shape: ECPolygonShape) {
373	        const points = shape.points;
374	        const stackedOnPoints = shape.stackedOnPoints;
375	
376	        let i = 0;
377	        let len = points.length / 2;
378	        const smoothMonotone = shape.smoothMonotone;
379	
380	        if (shape.connectNulls) {
381	            // Must remove first and last null values avoid draw error in polygon
382	            for (; len > 0; len--) {
383	                if (!isPointNull(points[len * 2 - 2], points[len * 2 - 1])) {
384	                    break;
385	                }
386	            }
387	            for (; i < len; i++) {
388	                if (!isPointNull(points[i * 2], points[i * 2 + 1])) {
389	                    break;
390	                }
391	            }
392	        }
393	        while (i < len) {
394	            const k = drawSegment(
395	                ctx, points, i, len, len,
396	                1,
397	                shape.smooth,
398	                smoothMonotone, shape.connectNulls
399	            );
400	            drawSegment(
401	                ctx, stackedOnPoints, i + k - 1, k, len,
402	                -1,
403	                shape.stackedOnSmooth,
404	                smoothMonotone, shape.connectNulls
405	            );
406	            i += k + 1;
407	
408	            ctx.closePath();
409	        }
410	    }
